# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_26_524_2", r"$x(x^{2}-y)\le0$: при $x\ge0$: $x^{2}-y\le0\Rightarrow y\ge x^{2}$; при $x\le0$: $x^{2}-y\ge0\Rightarrow y\le x^{2}$ (в частности вся ось $x=0$). В ключе для $x\le0$ стояло $y=x^{2}$ вместо $y\le x^{2}$",
  k=r"$x \ge 0$ и $y \ge x^{2}$ или $x \le 0$ и $y \le x^{2}$",
  dnew={2: (r"$x \ge 0$ и $y \le x^{2}$ или $x \le 0$ и $y \ge x^{2}$", r"Ученик верно разобрал два случая по знаку $x$, но перепутал знак неравенства для второго множителя: при $x\ge0$ нужно $x^{2}-y\le0$, то есть $y\ge x^{2}$.")})
E("G9_TB_27_539_3", r"$9^{-5}\cdot\left(\frac19\right)^{-3}=3^{-10}\cdot3^{6}=3^{-4}=\frac1{81}$ (ключ $\frac19$ неверен)",
  k=r"$3^{-4}=\dfrac{1}{81}$",
  dnew={0: (r"$81$", r"Ученик получил $9^{-5}\cdot9^{3}=9^{-2}$, но записал $9^{-2}=9^{2}=81$, потеряв знак показателя."),
        1: (r"$\dfrac{1}{9}$", r"Ученик верно записал $9^{-5}\cdot9^{3}=9^{-2}$ и принял $9^{-2}$ за $9^{-1}=\frac19$ (потерял множитель $2$ при переходе к основанию $3$: $3^{-4}=\frac1{81}$)."),
        2: (r"$\dfrac{1}{729}$", r"Ученик перевёл в основание $3$ верно ($3^{-10}\cdot3^{6}$), но при сложении показателей получил $-10+6=-3$ вместо $-4$.")})
E("G9_TB_27_542_2", r"запись «$b+25d$» без индекса читается как другая величина; верно $b_{1}+25d$",
  k=r"$b_{1} + 25d$")
E("G9_TB_27_545_1", r"$d=-1-\frac13=-\frac43$; $a_{10}=\frac13+9\cdot\left(-\frac43\right)=\frac13-12=-11\frac23=-\frac{35}{3}$ (в ключе $-12\frac13$)",
  k=r"$a_{10} = -11\dfrac{2}{3}$, $a_{n} = \dfrac{1}{3} - \dfrac{4}{3}(n-1)$",
  dnew={2: (r"$a_{10} = -12\dfrac{1}{3}$, $a_{n} = \dfrac{1}{3} - \dfrac{4}{3}(n-1)$", r"Ученик верно записал формулу $n$-го члена, но при подстановке $n=10$ ошибся в арифметике: $9\cdot\frac43=12$, а не $12\frac23$, поэтому $a_{10}=\frac13-12=-11\frac23$.")})
